#!/data/data/com.termux/files/usr/bin/bash\nset -e\n\nAPP_DIR="$(cd "$(dirname "$0")" && pwd)"\nPREFIX_BIN="$PREFIX/bin"\n\ncommand -v python3 >/dev/null 2>&1 || { echo "Python 3 is required: pkg install python"; exit 1; }\ncommand -v ffmpeg >/dev/null 2>&1 || { echo "FFmpeg is required: pkg install ffmpeg"; exit 1; }\n\nmkdir -p "$PREFIX_BIN"\n\nprintf '%s\n' '#!/data/data/com.termux/files/usr/bin/bash' "exec python3 \"$APP_DIR/ary_episode_watcher.py\" \"\$@\"" > "$PREFIX_BIN/aryweb"\nchmod +x "$PREFIX_BIN/aryweb"\ncp "$PREFIX_BIN/aryweb" "$PREFIX_BIN/arycheck"\n\necho "Installed aryweb and arycheck for $APP_DIR"\necho "Start with: aryweb"\necho "Open: http://127.0.0.1:8787"